const fs = require('fs');

const data = fs.readFileSync(0, 'utf-8').trim().split(/\s+/).map(Number);
let ptr = 0;
const nextInt = () => data[ptr++];

class Interval {
    constructor(l, r) {
        this.l = l;
        this.r = r;
    }
}

function binarySearch(arr, value) {
    let low = 0;
    let high = arr.length - 1;
    while (low <= high) {
        const mid = (low + high) >> 1;
        if (arr[mid].l < value.l) {
            low = mid + 1;
        } else if (arr[mid].l > value.l) {
            high = mid - 1;
        } else {
            return mid;
        }
    }
    return ~low;
}

function find(dp, value, index) {
    for (let i = index - 2; i >= 0; i--) {
        const arr = dp[i];
        if (arr.length === 0) continue;
        const ind = binarySearch(arr, value);
        if (ind < 0) {
            ind = (~ind) - 1;
            if (ind >= 0 && arr[ind].r >= value.r) {
                return true;
            }
        } else {
            if (arr[ind].r >= value.r) return true;
        }
    }
    return false;
}

function solve() {
    const n = nextInt();
    const k = nextInt();

    const l = new Array(k);
    const r = new Array(k);
    for (let i = 0; i < k; i++) {
        l[i] = nextInt();
        r[i] = nextInt();
    }

    const size = 2 * k + 1;
    const dp = new Array(size);
    for (let i = 0; i < size; i++) {
        dp[i] = [];
    }
    dp[0].push(new Interval(0, 0));

    let prev = 0;
    for (let i = 0; i < k; i++) {
        const next = new Array(size);
        for (let ii = 0; ii < size; ii++) {
            next[ii] = [];
        }

        let delta = l[i] - prev;
        for (let index = 0; index < size; index++) {
            if (index % 2 === 0) {
                for (const interval of dp[index]) {
                    interval.l += delta;
                    interval.r += delta;
                }
            }
        }

        delta = r[i] - l[i];
        for (let ii = 0; ii < size; ii++) {
            if (ii % 2 === 0) {
                for (const interval of dp[ii]) {
                    next[ii].push(new Interval(interval.l + delta, interval.r + delta));
                    if (ii + 1 < size) next[ii + 1].push(new Interval(interval.l, interval.r + delta));
                    if (ii + 2 < size) next[ii + 2].push(new Interval(interval.l, interval.r + delta));
                }
            } else {
                for (const interval of dp[ii]) {
                    next[ii].push(new Interval(interval.l, interval.r));
                    if (ii + 1 < size) next[ii + 1].push(new Interval(interval.l, interval.r + delta));
                    if (ii + 2 < size) next[ii + 2].push(new Interval(interval.l, interval.r + delta));
                }
            }
        }

        prev = r[i];
        for (let index = 0; index < size; index++) {
            dp[index].length = 0;

            next[index].sort((a, b) => a.l - b.l);

            let pr = null;
            for (const interval of next[index]) {
                if (interval.l > n) break;
                if (pr !== null && pr.r >= interval.l) {
                    pr.r = Math.max(pr.r, interval.r);
                } else {
                    if (pr !== null && !find(dp, pr, index)) {
                        dp[index].push(pr);
                    }
                    pr = interval;
                }
            }
            if (pr !== null && !find(dp, pr, index)) {
                dp[index].push(pr);
            }
        }
    }

    const delta = 2 * n - prev;
    for (let index = 0; index < size; index++) {
        if (index % 2 === 0) {
            for (const interval of dp[index]) {
                interval.l += delta;
                interval.r += delta;
            }
        }
    }

    for (let i = 0; i < size; i++) {
        for (const interval of dp[i]) {
            if (interval.l <= n && interval.r >= n) {
                console.log("Full");
                console.log(i);
                return;
            }
        }
    }

    console.log("Hungry");
}

solve();

