using System.Text;

namespace Cutlet
{
    internal class Program
    {
        private static readonly StreamReader reader = new StreamReader(Console.OpenStandardInput(1024*10), Encoding.ASCII, false, 1024*10);
        private static readonly StreamWriter writer = new StreamWriter(Console.OpenStandardOutput(1024*10), Encoding.ASCII, 1024*10);

        private static void Main(string[] args)
        {
            Solve(args);
            writer.Flush();
        }

        private static void Solve(string[] args)
        {
            int n = Next();
            int k = Next();

            var l = new int[k];
            var r = new int[k];
            for (int i = 0; i < k; i++)
            {
                l[i] = Next();
                r[i] = Next();
            }

            List<Interval>[] dp;
            dp = new List<Interval>[2*k + 1];

            for (int i = 0; i < dp.Length; i++)
            {
                dp[i] = new List<Interval>();
            }
            dp[0].Add(new Interval(0, 0));

            int prev = 0;
            for (int i = 0; i < k; i++)
            {
                var next = new List<Interval>[dp.Length];
                for (int ii = 0; ii < dp.Length; ii++)
                {
                    next[ii] = new List<Interval>();
                }

                int delta = l[i] - prev;
                for (int index = 0; index < dp.Length; index++)
                {
                    if (index%2 == 0)
                    {
                        List<Interval> t = dp[index];
                        foreach (Interval interval in t)
                        {
                            interval.l += delta;
                            interval.r += delta;
                        }
                    }
                }
                delta = r[i] - l[i];
                for (int ii = 0; ii < dp.Length; ii++)
                {
                    if (ii%2 == 0)
                    {
                        foreach (Interval interval in dp[ii])
                        {
                            next[ii].Add(new Interval(interval.l + delta, interval.r + delta));
                            next[ii + 1].Add(new Interval(interval.l, interval.r + delta));
                            next[ii + 2].Add(new Interval(interval.l, interval.r + delta));
                        }
                    }
                    else
                    {
                        foreach (Interval interval in dp[ii])
                        {
                            next[ii].Add(new Interval(interval.l, interval.r));
                            next[ii + 1].Add(new Interval(interval.l, interval.r + delta));
                            next[ii + 2].Add(new Interval(interval.l, interval.r + delta));
                        }
                    }
                }

                prev = r[i];
                for (int index = 0; index < dp.Length; index++)
                {
                    dp[index].Clear();

                    Interval pr = null;
                    foreach (Interval interval in next[index].OrderBy(t => t.l))
                    {
                        if (interval.l > n)
                            break;
                        if (pr != null && pr.r >= interval.l)
                        {
                            pr.r = Math.Max(pr.r, interval.r);
                        }
                        else
                        {
                            if (pr != null && !Find(dp, pr, index))
                                dp[index].Add(pr);
                            pr = interval;
                        }
                    }
                    if (pr != null && !Find(dp, pr, index))
                        dp[index].Add(pr);
                }
            }

            {
                int delta = 2*n - prev;
                for (int index = 0; index < dp.Length; index++)
                {
